steps.text:
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
h1 {
  animation: fade-in 2s;
}

img {
  transition: transform 0.3s;
}
img:hover {
  transform: scale(1.2);
}

@keyframes spin {
  to { transform: rotate(360deg); }
}
img {
  animation: spin 4s linear infinite;
}

h1 {
  display: inline-block;
  background-image: linear-gradient(90deg, red, orange, gold, green, blue, purple);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
